package com.lucid.os.wallpapers;
import android.app.Activity;import android.app.WallpaperManager;import android.content.Intent;import android.graphics.BitmapFactory;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.Bundle;import android.view.View;import android.view.Window;import android.widget.Button;import android.widget.ImageView;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import java.io.InputStream;
/** Native Lucid wallpaper and colour controls; bundled art comes from the LucidOS Figma file. */
public final class MainActivity extends Activity{
 private static final int PICK_IMAGE=41,BG=0xfff5f4fa,INK=0xff1d1e2b,MUTED=0xff666778,BLUE=0xff0866ff;private LinearLayout content;
 @Override protected void onCreate(Bundle state){super.onCreate(state);Window w=getWindow();w.setStatusBarColor(BG);w.setNavigationBarColor(BG);w.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(12),dp(20),dp(28));scroll.addView(content);
 addLabel("PERSONALISATION",12,BLUE,true,0);addLabel("Wallpaper & style",28,INK,true,8);addLabel("Make the phone feel like yours.",14,MUTED,false,3);section("WALLPAPERS");
 content.addView(wallpaper("lucid-wallpaper-dusk.jpg","Dusk","The Lucid default"));content.addView(wallpaper("lucid-wallpaper-alpine.jpg","Alpine","A cooler, open horizon"));
 Button custom=new Button(this);custom.setText("Choose a photo");custom.setAllCaps(false);custom.setOnClickListener(v->choosePhoto());LinearLayout.LayoutParams cp=lp(-1,dp(52));cp.bottomMargin=dp(22);content.addView(custom,cp);section("COLOUR");content.addView(colours());setContentView(scroll);}
 private void section(String s){addLabel(s,11,MUTED,true,18);}
 private View wallpaper(String asset,String name,String detail){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(10),dp(10),dp(10),dp(12));card.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams c=lp(-1,-2);c.bottomMargin=dp(12);card.setLayoutParams(c);
 ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(shape(0xffe0dfee,12));image.setClipToOutline(true);try(InputStream in=getAssets().open(asset)){image.setImageBitmap(BitmapFactory.decodeStream(in));}catch(Exception ignored){}card.addView(image,lp(-1,dp(210)));
 LinearLayout row=new LinearLayout(this);row.setGravity(android.view.Gravity.CENTER_VERTICAL);LinearLayout col=new LinearLayout(this);col.setOrientation(1);col.addView(label(name,17,INK,true));col.addView(label(detail,13,MUTED,false));row.addView(col,new LinearLayout.LayoutParams(0,-2,1f));Button apply=new Button(this);apply.setText("Apply");apply.setAllCaps(false);apply.setOnClickListener(v->applyAsset(asset));row.addView(apply);LinearLayout.LayoutParams rp=lp(-1,-2);rp.topMargin=dp(6);card.addView(row,rp);return card;}
 private View colours(){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(14),dp(14),dp(12));card.setBackground(shape(Color.WHITE,18));card.addView(label("System colour",17,INK,true));TextView note=label("Accent colour for supported Android surfaces.",13,MUTED,false);LinearLayout.LayoutParams np=lp(-1,-2);np.topMargin=dp(4);np.bottomMargin=dp(10);card.addView(note,np);LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.addView(colour("Blue","#0866FF",BLUE));row.addView(colour("Violet","#7657FF",0xff7657ff));row.addView(colour("Cyan","#00AFC8",0xff00afc8));card.addView(row);return card;}
 private Button colour(String name,String seed,int color){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(shape(color,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(46),1f);p.setMargins(dp(3),0,dp(3),0);b.setLayoutParams(p);b.setOnClickListener(v->{try{if(LucidPalette.apply(this,seed))toast(name+" colour applied");else toast("System colour changes are unavailable in this build.");}catch(SecurityException e){toast("System colour changes require the built-in LucidOS app.");}catch(Exception e){toast("Could not change colour.");}});return b;}
 private void choosePhoto(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(i,PICK_IMAGE);}catch(Exception e){toast("No photo picker is available.");}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=PICK_IMAGE||result!=RESULT_OK||data==null||data.getData()==null)return;applyUri(data.getData());}
 private void applyAsset(String asset){try(InputStream in=getAssets().open(asset)){setWallpaper(in);toast("Wallpaper applied");}catch(Exception e){toast("Could not apply wallpaper.");}}
 private void applyUri(Uri uri){try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IllegalStateException();setWallpaper(in);toast("Photo set as wallpaper");}catch(Exception e){toast("Could not set that photo as wallpaper.");}}
 private void setWallpaper(InputStream in)throws Exception{WallpaperManager.getInstance(this).setStream(in,null,true,WallpaperManager.FLAG_SYSTEM);}
 private void addLabel(String s,int size,int color,boolean bold,int top){TextView v=label(s,size,color,bold);LinearLayout.LayoutParams p=lp(-1,-2);p.topMargin=dp(top);content.addView(v,p);}
 private TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);return t;}
 private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}